#!/bin/bash\n# Script de Inicialização - Suporte Técnico API\n# Use: bash start.sh\n\necho \"🚀 Iniciando Suporte Técnico API...\"\necho \"\"\n\n# Verificar se Node.js está instalado\nif ! command -v node &> /dev/null; then\n    echo \"❌ Node.js não está instalado. Instale de: https://nodejs.org/\"\n    exit 1\nfi\n\necho \"✅ Node.js encontrado: $(node --version)\"\necho \"\"\n\n# Verificar se npm está instalado\nif ! command -v npm &> /dev/null; then\n    echo \"❌ npm não está instalado\"\n    exit 1\nfi\n\necho \"✅ npm encontrado: $(npm --version)\"\necho \"\"\n\n# Instalar dependências se necessário\nif [ ! -d \"node_modules\" ]; then\n    echo \"📦 Instalando dependências...\"\n    npm install\n    echo \"\"\nelse\n    echo \"✅ Dependências já instaladas\"\n    echo \"\"\nfi\n\n# Exibir instruções\necho \"=== PRÓXIMOS PASSOS ===\"\necho \"\"\necho \"1. Para desenvolvimento local:\"\necho \"   npm run dev\"\necho \"\"\necho \"2. Para Cloudflare Pages (recomendado):\"\necho \"   npm run pages:dev\"\necho \"\"\necho \"3. Após iniciar, acesse:\"\necho \"   http://localhost:3000/init.html\"\necho \"\"\necho \"4. Configure o primeiro admin e dados de teste na página de inicialização\"\necho \"\"\necho \"📚 Documentação: Consulte QUICKSTART_PT.md\"\necho \"\"\n